import {tripDays,mealSlots,sizes,shirtTotals} from './trip.mjs';
const endpoint='https://sdfleesxvattrwcsavqc.supabase.co/functions/v1/reunion-api';
const $=(s)=>document.querySelector(s), $$=(s)=>[...document.querySelectorAll(s)];
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let year=new Date().getFullYear(),records=[],years=[],token=localStorage.getItem('reunion-session')||'',photoURLs=[],weatherSequence=0,loadingSequence=0;
const options=(current='')=>'<option value="">Choose a size</option>'+sizes.map(s=>`<option ${s===current?'selected':''}>${s}</option>`).join('');
const dataOf=(kind)=>records.filter(r=>r.kind===kind).map(r=>({...r.data,id:r.id}));
const trip=()=>dataOf('trip')[0]||{start:'',camp:'',sites:'',notes:''};
const format=(d,opts={month:'short',day:'numeric'})=>new Date(d+'T12:00:00Z').toLocaleDateString('en-US',{...opts,timeZone:'UTC'});
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
async function api(action,init={},extra={},requestYear=year){const u=new URL(endpoint);u.searchParams.set('action',action);u.searchParams.set('year',requestYear);Object.entries(extra).forEach(([k,v])=>u.searchParams.set(k,v));const r=await fetch(u,{...init,headers:{'x-reunion-session':token,...init.headers}});if(!r.ok){const err=await r.json().catch(()=>({error:'Connection failed. Please try again.'}));if(r.status===401&&action!=='login')lock();throw new Error(err.error);}return action==='photo'?r.blob():r.json();}
async function save(kind,data,id=crypto.randomUUID()){await api('save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,data,id})});await load();toast('Saved for the whole family.');}
async function run(button,fn){button.disabled=true;try{await fn();}catch(e){toast(e.message);}finally{button.disabled=false;}}
function showPage(){let page=location.hash.slice(1)||'overview';if(!['overview','meals','people','shirts','messages','photos'].includes(page))page='overview';$$('.page').forEach(p=>p.classList.toggle('active',p.id===page));$$('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));}
function renderYears(){years=[...new Set([...years,year])].sort((a,b)=>b-a);$('#year').innerHTML=years.map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('');}
async function load(){const seq=++loadingSequence;const selected=year;$('main').inert=true;try{const rows=await api('state');if(seq!==loadingSequence||selected!==year)return;records=rows;render();}finally{if(seq===loadingSequence)$('main').inert=false;}}
function render(){renderYears();const t=trip(),people=dataOf('person');const f=$('#trip-form');for(const k of ['start','camp','sites','notes'])f.elements[k].value=t[k]||'';f.elements.end.value=t.start?format(tripDays(t.start)[3],{weekday:'short',month:'short',day:'numeric',year:'numeric'}):'';
 $('#date-stat').textContent=t.start?format(t.start)+' – '+format(tripDays(t.start)[3]):'Pick our dates';
 const today=new Date().toLocaleDateString('en-CA',{timeZone:'America/Chicago'});const days=t.start?Math.round((+new Date(t.start+'T00:00:00Z')-+new Date(today+'T00:00:00Z'))/86400000):null;
 $('#countdown').textContent=days===null?'A reunion worth counting down to':days>0?days+' days until we’re together':days>=-3?'It’s reunion weekend!':'Another weekend in the memory books';
 $('#camp-stat').textContent=t.camp||'Choose our campsite';$('#site-stat').textContent=t.sites?'Sites '+t.sites:'Our gathering spot for the weekend';$('#crew-stat').textContent=people.length+' people & counting';
 renderMeals();renderPeople();renderShirts();renderMessages();renderPhotos();renderWeather();
}
function renderMeals(){const t=trip();if(!t.start){$('#meal-list').innerHTML='<div class="empty">Set your Friday arrival date on the Overview page to create the seven meal slots.</div>';return;}const meals=dataOf('meal');const slots=mealSlots(t.start);$('#meal-list').innerHTML=tripDays(t.start).slice(0,3).map(date=>`<div class="meal-day"><h2>${format(date,{weekday:'long',month:'short',day:'numeric'})}</h2><div class="meal-grid">${slots.filter(s=>s.date===date).map(s=>{const m=meals.find(m=>m.slot===s.id)||{};return `<article class="card"><h3>${s.meal}<span>${m.family?'Claimed':'Up for grabs'}</span></h3><form data-slot="${s.id}"><label>Family cooking<input name="family" maxlength="100" value="${esc(m.family)}" placeholder="Your family / household"></label><label>What’s on the menu?<textarea name="menu" maxlength="1000" placeholder="Main dish, sides, supplies needed…">${esc(m.menu)}</textarea></label><button class="button primary">Save meal</button></form></article>`;}).join('')}</div></div>`).join('');$$('#meal-list form').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();run(form.querySelector('button'),()=>save('meal',{slot:form.dataset.slot,...Object.fromEntries(new FormData(form))}));}));}
function deleteButton(kind,id){return `<button class="delete" data-delete="${esc(id)}" data-kind="${kind}">Remove</button>`;}
function bindDeletes(root){$$(root+' [data-delete]').forEach(b=>b.addEventListener('click',()=>{if(confirm('Remove this '+b.dataset.kind+' for everyone?'))run(b,async()=>{await api('delete',{method:'DELETE'},{id:b.dataset.delete});await load();toast('Removed.');});}));}
function renderPeople(){const people=dataOf('person');$('#people-list').innerHTML=people.length?people.map(p=>`<article class="card person"><h3>${esc(p.name)}</h3><p>${esc(p.family)}</p><p>${esc(p.size||'Shirt size needed')}</p>${p.diet?'<p>Food needs: '+esc(p.diet)+'</p>':''}<button class="button secondary" data-edit="${esc(p.id)}">Edit</button>${deleteButton('person',p.id)}</article>`).join(''):'<div class="empty">No one on the roster yet. Add the first member of the crew above.</div>';bindDeletes('#people-list');$$('[data-edit]').forEach(b=>b.onclick=()=>{const p=people.find(p=>p.id===b.dataset.edit);const f=$('#person-form');['name','family','size','diet'].forEach(k=>f.elements[k].value=p[k]||'');f.dataset.edit=p.id;f.querySelector('button').textContent='Save person';f.scrollIntoView({behavior:'smooth'});f.elements.name.focus();});}
function renderShirts(){const plan=dataOf('shirt')[0]||{};const form=$('#shirt-form');form.elements.color.value=plan.color||'';form.elements.notes.value=plan.notes||'';const people=dataOf('person');const totals=shirtTotals(people);const complete=people.filter(p=>p.size).length;$('#shirt-summary').textContent=complete+' sizes collected · '+(people.length-complete)+' still needed';$('#shirt-totals').innerHTML=Object.entries(totals).map(([size,count])=>`<span>${size} <b>× ${count}</b></span>`).join('')||'<p class="muted">Add people and their sizes to build your order.</p>';$('#shirt-list').innerHTML=people.map(p=>`<div class="size-row"><span>${esc(p.name)}<small>${esc(p.family)}</small></span><select aria-label="Shirt size for ${esc(p.name)}" data-person="${p.id}">${options(p.size)}</select></div>`).join('')||'<div class="empty">Your crew’s shirt sizes will appear here.</div>';$$('[data-person]').forEach(s=>s.onchange=()=>run(s,()=>{const p=people.find(p=>p.id===s.dataset.person);return save('person',{...p,size:s.value},p.id);}));}
function renderMessages(){const messages=dataOf('message').reverse();$('#message-list').innerHTML=messages.map(m=>`<article class="card message"><div class="message-top"><strong>${esc(m.author)}</strong><time>${esc(new Date(m.created).toLocaleString())}</time></div><p>${esc(m.text)}</p>${deleteButton('message',m.id)}</article>`).join('')||'<div class="empty">Start the conversation. Your family’s messages will show up here.</div>';bindDeletes('#message-list');}
async function renderPhotos(){photoURLs.forEach(u=>URL.revokeObjectURL(u));photoURLs=[];const photos=dataOf('photo').reverse(),thisYear=year;$('#photo-list').innerHTML=photos.map(p=>`<figure><img data-photo="${p.id}" alt="${esc(p.caption||'Family reunion photo')}" loading="lazy"><figcaption>${esc(p.caption)}<div><a data-download="${p.id}" download="talladega-${year}-${p.id}">Download</a>${deleteButton('photo',p.id)}</div></figcaption></figure>`).join('')||'<div class="empty">The album is ready for your first photo.</div>';bindDeletes('#photo-list');await Promise.all(photos.map(async p=>{try{const blob=await api('photo',{}, {id:p.id},thisYear);const img=$(`[data-photo="${p.id}"]`);if(year!==thisYear||!img)return;const u=URL.createObjectURL(blob);photoURLs.push(u);img.src=u;$(`[data-download="${p.id}"]`).href=u;}catch(e){const img=$(`[data-photo="${p.id}"]`);if(img)img.alt='Could not load photo. Refresh to retry.';}}));}
const descriptions={0:'Clear skies',1:'Mainly clear',2:'Partly cloudy',3:'Overcast',45:'Fog',48:'Fog',51:'Light drizzle',53:'Drizzle',55:'Heavy drizzle',61:'Light rain',63:'Rain',65:'Heavy rain',71:'Light snow',73:'Snow',75:'Heavy snow',80:'Rain showers',81:'Rain showers',82:'Heavy showers',95:'Thunderstorms',96:'Thunderstorms',99:'Thunderstorms'};
let weatherCache;
async function renderWeather(){const seq=++weatherSequence,t=trip(),el=$('#weather-content');if(!t.start){el.className='empty';el.textContent='Choose trip dates to see the weather outlook.';return;}const dates=tripDays(t.start);const today=new Date().toLocaleDateString('en-CA',{timeZone:'America/Chicago'});if(dates[3]<today){el.className='empty';el.textContent='This trip is in the memory books. Live forecasts are shown for upcoming trips.';return;}if((+new Date(t.start)-+new Date(today))/86400000>15){el.className='empty';el.textContent='A little early for the forecast. Check back within 16 days of the trip.';return;}el.className='';el.textContent='Loading the weekend outlook…';try{if(!weatherCache||Date.now()-weatherCache.at>1800000){const r=await fetch('https://api.open-meteo.com/v1/forecast?latitude=33.6132&longitude=-86.1183&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max&temperature_unit=fahrenheit&timezone=America%2FChicago&forecast_days=16');if(!r.ok)throw new Error();weatherCache={at:Date.now(),data:(await r.json()).daily};}if(seq!==weatherSequence)return;const d=weatherCache.data;el.innerHTML=dates.map(date=>{const i=d.time.indexOf(date);return `<div class="forecast-day"><div><strong>${format(date,{weekday:'short',month:'short',day:'numeric'})}</strong><small>${i<0?'Forecast not available yet':esc(descriptions[d.weather_code[i]]||'Mixed conditions')}</small>${i<0?'':`<small>${d.precipitation_probability_max[i]??'—'}% chance of rain</small>`}</div>${i<0?'':`<b>${d.temperature_2m_max[i]===null?'—':Math.round(d.temperature_2m_max[i])}° / ${d.temperature_2m_min[i]===null?'—':Math.round(d.temperature_2m_min[i])}°F</b>`}</div>`;}).join('');}catch{if(seq!==weatherSequence)return;el.className='empty';el.textContent='Weather is temporarily unavailable. Your trip plans are still saved.';}}
$('#trip-form').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;run(f.querySelector('button'),async()=>{const d=Object.fromEntries(new FormData(f));tripDays(d.start);if(Number(d.start.slice(0,4))!==year)throw new Error('Choose a Friday in '+year+'.');if(trip().start&&trip().start!==d.start&&dataOf('meal').some(m=>m.family)&&!confirm('Changing dates creates new meal slots. Existing assignments stay saved with their original dates. Continue?'))return;await save('trip',d);});});
$('#trip-form').elements.start.onchange=e=>{try{$('#trip-form').elements.end.value=format(tripDays(e.target.value)[3],{weekday:'short',month:'short',day:'numeric',year:'numeric'});}catch{$('#trip-form').elements.end.value='Choose a Friday';}};
$('#person-form .sizes').innerHTML=options();$('#person-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;run(f.querySelector('button'),async()=>{await save('person',Object.fromEntries(new FormData(f)),f.dataset.edit||crypto.randomUUID());f.reset();delete f.dataset.edit;f.querySelector('button').textContent='Add to the crew';});};
$('#shirt-form').onsubmit=e=>{e.preventDefault();run(e.currentTarget.querySelector('button'),()=>save('shirt',Object.fromEntries(new FormData(e.currentTarget))));};
$('#message-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;run(f.querySelector('button'),async()=>{await save('message',Object.fromEntries(new FormData(f)));f.elements.text.value='';});};
$('#photo-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;run(f.querySelector('button'),async()=>{const uploadYear=year;const files=[...f.elements.files.files];for(const file of files){if(file.size>10485760||!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Use JPEG, PNG or WebP photos, each under 10 MB.');}let done=0;try{for(const file of files){const body=new FormData();body.append('file',file);body.append('caption',f.elements.caption.value);await api('upload',{method:'POST',body},{},uploadYear);done++;}f.reset();toast(done+' photo'+(done===1?'':'s')+' added to the family album.');}finally{await load();}});};
$('#export-shirts').onclick=()=>{const cell=s=>'"'+String(s).replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';const rows=[['Name','Family','Shirt size'],...dataOf('person').map(p=>[p.name,p.family,p.size||'NEEDED'])];const url=URL.createObjectURL(new Blob([rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='talladega-shirts-'+year+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('#year').onchange=e=>{year=Number(e.target.value);run(e.target,load);};$('#new-year').onclick=()=>{$('#new-year-value').value=Math.max(...years,year)+1;$('#year-dialog').showModal();};$('#year-dialog').addEventListener('close',()=>{if($('#year-dialog').returnValue==='add'){const y=Number($('#new-year-value').value);if(y>=2000&&y<=2100){year=y;run($('#new-year'),async()=>{await load();if(!dataOf('trip').length)await save('trip',{start:'',camp:'',sites:'',notes:''});});}}});
$('#plan-trip').onclick=()=>{$('#trip-form').scrollIntoView({behavior:'smooth'});$('#trip-form').elements.start.focus({preventScroll:true});};window.addEventListener('hashchange',showPage);showPage();
function lock(){token='';localStorage.removeItem('reunion-session');document.body.classList.add('locked');$('#login-password').focus();}
async function unlock(){years=await api('years');if(years.length&&!years.includes(year))year=years[0];await load();document.body.classList.remove('locked');}
$('#login-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;run(f.querySelector('button'),async()=>{const result=await api('login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:$('#login-password').value})});token=result.token;if($('#remember').checked)localStorage.setItem('reunion-session',token);else localStorage.removeItem('reunion-session');$('#login-password').value='';await unlock();});};
$('#logout').onclick=lock;$('#refresh').onclick=e=>run(e.currentTarget,async()=>{await load();toast('Up to date.');});
if(token)unlock().catch(e=>{lock();toast(e.message);});else lock();
